import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"夬","description":"周易集解 - 夬","frontmatter":{"title":"夬","description":"周易集解 - 夬"},"headers":[],"relativePath":"classics/jijie/043.md","filePath":"classics/jijie/043.md"}'),l={name:"classics/jijie/043.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="夬" tabindex="-1">夬 <a class="header-anchor" href="#夬" aria-label="Permalink to “夬”">​</a></h1><h2 id="夬-1" tabindex="-1">夬 <a class="header-anchor" href="#夬-1" aria-label="Permalink to “夬”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>夬，揚於王庭。孚號有厲，告自邑。不利即戎，利有攸往。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：益而不已必決，故受之以夬。夬者，決也。</p><p>韓康伯曰：益而不已則盈，故必決矣。</p><p>虞翻曰：陽決陰，息卦也。剛決柔，與剝旁通。乾為陽，為王，剝艮為庭，故揚於王庭矣。</p><p>鄭玄曰：夬，決也。陽氣浸長，至於五，五，尊位也。而陰先之，是猶聖人積德說天下，以漸消去小人，至於受命為天子，故謂之決。揚，越也。五互體乾。乾為君，又居尊位，王庭之象也。陰爻越其上，小人乘君子，罪惡上聞於聖人之朝，故曰｢夬，揚於王庭｣也。</p><p>虞翻曰：陽在二五稱孚。孚，謂五也。二失位，動體巽，巽為號，離為光。不變則危。故｢孚號有厲，其危乃光也｣。</p><p>虞翻曰：陽息動復。剛長成夬。震為告。坤為自邑。夬從復升，坤逆在上，民眾消滅。二變時，離為戎。故｢不利即戎，所尚乃窮也。｣</p><p>虞翻曰：陽息陰消，君子道長，故｢利有攸往，剛長乃終｣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：夬，決也，剛決柔也。健而說，決而和。揚於王庭，柔乘五剛也。孚號有厲，其危乃光也。告自邑，不利即戎，所尚乃窮也。利有攸往，剛長乃終也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：乾決坤也。</p><p>虞翻曰：健，乾。說，兌也。以乾陽獲陰之和，故決而和也。</p><p>王弼曰：剛德浸長，一柔為逆，眾所同誅，而無忌者也。故可揚於王庭。</p><p>荀爽曰：信其號令於下，眾陽危。去上六，陽乃光明也。</p><p>乾寶曰：夬九五則飛龍在天之爻也。應天順民，以發號令，故曰孚號。以柔決剛，以臣伐君，君子危之，故曰有厲。德大即心小，功高而意下，故曰其危乃光也。</p><p>翟玄曰：坤稱邑也。</p><p>乾寶曰：殷民告周以紂無道。</p><p>荀爽曰：不利即尚兵戎，而與陽爭，必困窮。</p><p>虞翻曰：乾體大成，以決小人。終乾之剛，故乃以終也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：澤上於天，夬。君子以施祿及下，居德則忌。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>陸績曰：水氣上天，決降成雨。故曰夬。</p><p>虞翻曰：君子謂乾，乾為施祿。下為剝坤，坤為眾臣。以乾應坤，故施祿及下。乾為德，艮為居，故居德則忌。陽極陰生，謂陽忌陰。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，壯於前趾，往不勝為咎。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：夬變大壯，大壯震為趾，位在前，故壯於前。剛以應剛，不能克之，往如失位，故往不勝為咎。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不勝而往，咎也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：往失位應陽，故咎矣。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，惕號，莫夜有戎，勿恤。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：惕，懼也。二失位，故惕。變成巽，故號。剝坤為莫夜。二動成離，離為戎，變而得正，故有戎。四變成坎，坎為憂，坎又得正，故勿恤。謂成既濟定也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：有戎勿恤，得中道也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：動得正應五，故得中道。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，壯於頄，有兇。君子夬夬，獨行遇雨。若濡有慍，無咎。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>翟玄曰：頄，面也。謂上處乾首之前，稱頄。頄，頰間骨。三往壯上，故有兇也。</p><p>荀爽曰：九三體乾，乾為君子。三五同功，二爻俱欲決上，故曰君子夬夬也。獨行謂一爻獨上，與陰相應，為陰所施，故遇雨也。</p><p>荀爽曰：雖為陰所濡，能慍不說，得無咎也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：君子夬夬，終無咎也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：頄，面顴也。謂上六矣。最處體上，故曰頄也。剝之六三，以應陽為善。夫剛長則君子道興，陰盛則小人道長。然則處陰長而助陽則善，處剛長而助柔則兇矣。而三獨應上，助小人，是以兇也。君子處之，必能棄夫情累，決之不疑，故曰夬夬也。若不與陽為群，而獨行殊志，應於小人，則受其困焉。遇雨若濡有慍，而終無所咎也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，臀無膚，其行次且。牽羊悔亡，聞言不信。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：二四已變，坎為臀。剝艮為膚，毀滅不見。故臀無膚。大壯震為行。坎為破，為曳。故其行次且也。</p><p>虞翻曰：兌為羊，二變巽為繩，剝艮手持繩，故牽羊。謂四之正，得位承五，故悔亡。震為言，坎為耳，震坎象不正，故聞言不信也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：其行次且，位不當也。聞言不信，聰不明也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：坎耳離目，折入於兌，故聰不明矣。</p><p>案：兌為羊，四五體兌故也。凡卦，初為足，二為腓，三為股，四為臀，當陰柔，今反剛陽，故曰臀無膚。九四震爻，震為足，足既不正，故行次且矣。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，陸夬夬，中行無咎。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>荀爽曰：莧謂五，陸謂三。兩爻決上，故曰夬夬也。莧者，葉柔而根堅且赤，以言陰在上六也。陸亦取葉柔根堅也。去陰遠，故言陸。言差堅於莧。莧根小，陸根大。五體兌，柔居上，莧也。三體乾，剛在下，根深，故謂之陸也。</p><p>虞翻曰：，說也。，讀夫子莞爾而笑之。睦，和睦也。震為笑。言五得正位，兌為說，故陸夬夬。大壯震為行，五在上中，動而得正，故中行無咎。舊讀言莧陸，字之誤也。馬君、荀氏皆從俗，言莧陸非也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：中行無咎，中未光也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：在坎陰中，故未光也。</p><p>王弼曰：莧，草之柔脆者也。夬之至易，故曰夬夬也。夬之為義，以剛決柔，以君子除小人也。而五處尊位，最比小人，躬自決者也。夫以至尊而敵於至賤，雖其克勝，未足多也。處中而行，足以免咎而已，未為光益也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，無號，終有兇。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：應在於三，三動時體巽，巽為號令；四已變坎，之應歷險，巽象不見，故無號。位極乘陽，故終有兇矣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：無號之兇，終不可長也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：陰道消滅，故不可長也。</p>',83)])])}const m=e(l,[["render",p]]);export{b as __pageData,m as default};
